const technicalAssignmentId = String(
  $('POST /analysis/v2/pdf').first().json.body?.technical_assignment_id ?? '',
).trim();

if (!technicalAssignmentId) {
  return [{
    json: {
      enabled: false,
      technical_assignment_id: null,
      analysis_document_id: null,
      section_id: null,
      source_file: '',
      source_sha256: '',
      total: 0,
      requirements: [],
    },
  }];
}

const pages = $input.all().map((item) => item.json ?? {});

if (pages.length === 0) {
  throw new Error('T-first requirement feed вернул пустой набор страниц.');
}

const first = pages[0];
const expectedDocumentId = String(
  $('POST /analysis/v2/pdf').first().json.body?.technical_assignment_analysis_document_id ?? '',
).trim();

if (!expectedDocumentId) {
  throw new Error(
    'T-first orchestration не содержит technical_assignment_analysis_document_id.',
  );
}

const expectedSectionId = String(
  $('POST /analysis/v2/pdf').first().json.body?.normative_section_id ?? '',
).trim();

const total = Number(first.total ?? 0);

if (!Number.isInteger(total) || total < 1) {
  throw new Error(
    `T-first requirement feed должен содержать хотя бы одно atomic requirement; total=${first.total}.`,
  );
}

if (total > 1000) {
  throw new Error(
    `T-first requirement feed превышает configured Analysis limit: total=${total}, limit=1000.`,
  );
}

const requirements = pages
  .flatMap((page) => Array.isArray(page.requirements) ? page.requirements : [])
  .sort(
    (left, right) =>
      Number(left.requirement_index ?? 0) - Number(right.requirement_index ?? 0),
  );

for (const page of pages) {
  if (String(page.technical_assignment_id ?? '') !== technicalAssignmentId) {
    throw new Error('T-first requirement feed содержит другой technical_assignment_id.');
  }

  if (String(page.analysis_document_id ?? '') !== expectedDocumentId) {
    throw new Error('T-first requirement feed содержит другой analysis_document_id.');
  }

  if (String(page.section_id ?? '') !== expectedSectionId) {
    throw new Error('T-first requirement feed содержит другой section_id.');
  }

  if (Number(page.total ?? -1) !== total) {
    throw new Error('T-first requirement feed содержит несовместимые total между страницами.');
  }

  if (
    String(page.source_file ?? '') !== String(first.source_file ?? '')
    || String(page.source_sha256 ?? '') !== String(first.source_sha256 ?? '')
  ) {
    throw new Error('T-first requirement feed содержит несовместимые source metadata.');
  }
}

if (requirements.length !== total) {
  throw new Error(
    `T-first requirement feed получен не полностью: expected=${total}, actual=${requirements.length}.`,
  );
}

const requirementIds = requirements.map(
  (requirement) => String(requirement.requirement_id ?? ''),
);

if (
  requirementIds.some((requirementId) => !requirementId)
  || new Set(requirementIds).size !== requirementIds.length
) {
  throw new Error('T-first requirement feed содержит пустые или повторяющиеся requirement_id.');
}

return [{
  json: {
    enabled: true,
    technical_assignment_id: technicalAssignmentId,
    analysis_document_id: expectedDocumentId,
    section_id: expectedSectionId,
    source_file: String(first.source_file ?? ''),
    source_sha256: String(first.source_sha256 ?? ''),
    total,
    requirements,
  },
}];

const document = $('Document Extract PDF').first().json;
const validation = $('Validate Project Context').first().json;
const context = $('Create Project Context').first().json;
const technicalAssignment = $input.first().json;
const pages = Array.isArray(document.pages) ? document.pages : [];

return pages.map((page) => ({
  json: {
    document: {
      file_name: document.file_name ?? 'document.pdf',
      total_pages: document.total_pages ?? pages.length,
      selected_pages: document.selected_pages ?? pages.map((item) => item.page_number),
    },
    project_context: {
      context_id: context.context_id,
      enabled: context.enabled ?? false,
      start_page: document.explanatory_note_context?.start_page ?? null,
      end_page: document.explanatory_note_context?.end_page ?? null,
      pages_count: context.pages_count ?? 0,
      indexed_chunks: context.chunks_count ?? 0,
      vector_size: context.vector_size ?? 0,
      cache_key: context.cache_key ?? null,
      cache_hit: Boolean(context.cache_hit),
      collection_name: context.collection_name ?? null,
      validation,
    },
    technical_assignment: technicalAssignment,
    page,
  },
}));

const understoodPages = $('Understand Page')
  .all()
  .map((item) => item.json);

if (!understoodPages.length) {
  throw new Error(
    'T-first normalization не получила understood pages.',
  );
}

const enabled = Boolean(
  understoodPages[0]?.expanded
    ?.technical_assignment?.enabled,
);

if (!enabled) {
  return understoodPages.map((page) => ({
    json: {
      ...page,
      enabled: false,
      requirements_count: 0,
      summary: '',
      decisions: [],
      findings: [],
      metrics: [],
    },
  }));
}

const batchItems = Array.isArray(
  $input.first().json.items,
)
  ? $input.first().json.items
  : [];

if (batchItems.length !== understoodPages.length) {
  throw new Error(
    `T-first stage потеряла страницы: expected=${understoodPages.length}, actual=${batchItems.length}.`,
  );
}

const byPage = new Map(
  batchItems.map((item) => [
    Number(item.page_number ?? 0),
    item.result ?? {},
  ]),
);

return understoodPages.map((page) => {
  const pageNumber = Number(
    page.expanded?.page?.page_number ?? 0,
  );

  const response = byPage.get(pageNumber);

  if (!response) {
    throw new Error(
      `T-first stage не вернула страницу ${pageNumber}.`,
    );
  }

  const decisions = Array.isArray(response.decisions)
    ? response.decisions
    : [];

  const findings = Array.isArray(response.findings)
    ? response.findings
    : [];

  const metrics = Array.isArray(response.metrics)
    ? response.metrics
    : [];

  const requirements = Array.isArray(
    page.expanded?.technical_assignment?.requirements,
  )
    ? page.expanded.technical_assignment.requirements
    : [];

  const expectedIds = requirements.map(
    (requirement) =>
      String(requirement.requirement_id ?? ''),
  );

  const actualIds = decisions.map(
    (decision) =>
      String(decision.requirement_id ?? ''),
  );

  if (
    actualIds.length !== expectedIds.length
    || actualIds.some((id) => !id)
    || new Set(actualIds).size !== actualIds.length
    || expectedIds.some(
      (id, index) => id !== actualIds[index],
    )
  ) {
    throw new Error(
      `T-first decisions страницы ${pageNumber} не соответствуют полному ordered atomic requirement feed.`,
    );
  }

  return {
    json: {
      ...page,
      enabled: true,
      requirements_count: expectedIds.length,
      summary: String(response.summary ?? ''),
      decisions,
      findings,
      metrics,
    },
  };
});

