const normativeCheck = $json ?? {};

const normativeFindings = Array.isArray(
  normativeCheck.findings,
)
  ? normativeCheck.findings
  : [];

const pageIndex = Number(
  normativeCheck.page_index ?? $itemIndex,
);

const technicalAssignment =
  $('Technical Assignment First Pass')
    .all()[pageIndex]?.json ?? {};

const technicalAssignmentFindings =
  Array.isArray(technicalAssignment.findings)
    ? technicalAssignment.findings
    : [];

const findings = [
  ...normativeFindings,
  ...technicalAssignmentFindings,
];

const findingIds = findings.map(
  (finding) =>
    String(finding.finding_id ?? ''),
);

if (
  findingIds.some((findingId) => !findingId)
  || new Set(findingIds).size
    !== findingIds.length
) {
  throw new Error(
    'Finding candidate merge обнаружил пустой или повторяющийся finding_id.',
  );
}

return {
  json: {
    ...normativeCheck,
    findings,
    technical_assignment_first_pass: {
      enabled:
        Boolean(technicalAssignment.enabled),
      requirements_count:
        Number(
          technicalAssignment.requirements_count
          ?? 0,
        ),
      decisions_count:
        Array.isArray(technicalAssignment.decisions)
          ? technicalAssignment.decisions.length
          : 0,
      findings_count:
        technicalAssignmentFindings.length,
      summary:
        String(technicalAssignment.summary ?? ''),
      metrics:
        Array.isArray(technicalAssignment.metrics)
          ? technicalAssignment.metrics
          : [],
    },
  },
};

const findings = Array.isArray($json.findings) ? $json.findings : [];

const normativeQueryItems = findings
  .map((finding) => {
    const findingQuery = String(finding.experience_query ?? '').trim();
    if (!findingQuery) {
      return null;
    }

    return {
      finding_id: String(finding.finding_id ?? ''),
      query: [
        'Найти нормативное основание для уже обнаруженного инженерного замечания.',
        'Нужен фрагмент нормативного документа, который прямо относится к указанному факту и типу проектного документа.',
        'Не считать тематически похожий норматив достаточным подтверждением.',
        findingQuery,
      ].join('\n'),
    };
  })
  .filter((item) => item?.finding_id && item?.query);

return {
  json: {
    findings,
    normative_query_items: normativeQueryItems,
    normative_queries: normativeQueryItems.map((item) => item.query),
  },
};

const prepared = $('Prepare Finding Normative Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const queryItems = Array.isArray(prepared.normative_query_items)
  ? prepared.normative_query_items
  : [];
const results = Array.isArray($json.results) ? $json.results : [];

const normativeCandidatesByFinding = {};

for (const finding of findings) {
  normativeCandidatesByFinding[String(finding.finding_id ?? '')] = [];
}

for (let index = 0; index < queryItems.length; index += 1) {
  const queryItem = queryItems[index] ?? {};
  const findingId = String(queryItem.finding_id ?? '');
  if (!findingId) {
    continue;
  }

  const result = results[index] ?? {};
  const rawSources = Array.isArray(result.sources) ? result.sources : [];

  normativeCandidatesByFinding[findingId] = rawSources.map(
    (source, sourceIndex) => ({
      ...source,
      source_id: `NQ${index + 1}_${sourceIndex + 1}`,
    }),
  );
}

return {
  json: {
    findings,
    normative_candidates_by_finding: normativeCandidatesByFinding,
    experience_queries: findings
      .map((finding) => String(finding.experience_query ?? '').trim())
      .filter((query) => query.length > 0),
  },
};

const prepared = $('Prepare Experience Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const normativeCandidatesByFinding =
  prepared.normative_candidates_by_finding
  && typeof prepared.normative_candidates_by_finding === 'object'
    ? prepared.normative_candidates_by_finding
    : {};
const results = Array.isArray($json.results) ? $json.results : [];
const experienceByFinding = {};

for (let index = 0; index < findings.length; index += 1) {
  const finding = findings[index];
  const result = results[index] ?? {};
  experienceByFinding[finding.finding_id] = Array.isArray(result.sources)
    ? result.sources
    : [];
}

return {
  json: {
    findings,
    normative_candidates_by_finding: normativeCandidatesByFinding,
    experience_by_finding: experienceByFinding,
  },
};

const index = Number(
  $json.page_index ?? $itemIndex,
);

const prepared =
  $('Technical Assignment First Pass')
    .all()[index]?.json ?? {};

const expanded =
  prepared.expanded ?? {};

const understanding = {
  facts:
    prepared.facts ?? {},
  metrics:
    prepared.understanding_metrics ?? {},
};

const queries =
  $('Build Normative Queries')
    .all()[index]?.json ?? {};

const requirements =
  $('Normalize Requirement Search')
    .all()[index]?.json ?? {};

const userPackages =
  $('Search User Packages')
    .all()[index]?.json ?? {};

const check =
  $('Gate Expand Norm Check Stage')
    .all()[index]?.json ?? {};

const merged =
  $('Merge Finding Candidates')
    .all()[index]?.json ?? {};

const tFirst = prepared;

const enrichment =
  $('Prepare Experience Queries')
    .all()[index]?.json ?? {};

const augmentation =
  $('Augment Project Context')
    .all()[index]?.json ?? {};

const findingQuery =
  $('Prepare Finding Normative Queries')
    .all()[index]?.json ?? {};

const finalization =
  $json.finalization ?? {};

const findings = (
  finalization.findings ?? []
).map((finding) => ({
  ...finding,
  project_context_sources:
    augmentation.sources ?? [],
}));

const candidatesByFinding =
  enrichment.normative_candidates_by_finding
  && typeof enrichment.normative_candidates_by_finding
    === 'object'
    ? enrichment.normative_candidates_by_finding
    : {};

const candidateGroups = Object.values(
  candidatesByFinding,
).filter(
  (value) => Array.isArray(value),
);

const candidatesCount = candidateGroups
  .reduce(
    (total, sources) =>
      total + sources.length,
    0,
  );

const findingsWithCandidates =
  candidateGroups
    .filter(
      (sources) => sources.length > 0,
    )
    .length;

const tDecisions = Array.isArray(
  tFirst.decisions,
)
  ? tFirst.decisions
  : [];

return {
  json: {
    document:
      expanded.document,
    project_context:
      expanded.project_context,
    page_number:
      expanded.page.page_number,
    heuristic_page_type:
      expanded.page.page_type,
    width_points:
      expanded.page.width_points,
    height_points:
      expanded.page.height_points,
    extracted_text:
      expanded.page.text,
    facts:
      understanding.facts ?? {},
    normative_queries:
      queries.queries ?? [],
    normative_sources:
      requirements.normative_sources ?? [],
    technical_assignment_sources:
      requirements.technical_assignment_sources ?? [],
    conflict_candidates:
      requirements.conflict_candidates ?? [],
    requirement_diagnostics:
      requirements.diagnostics ?? [],
    reference_resolutions:
      requirements.reference_resolutions ?? [],
    user_package_sources:
      userPackages.sources ?? [],
    technical_assignment_first_pass: {
      enabled:
        Boolean(tFirst.enabled),
      requirements_count:
        Number(tFirst.requirements_count ?? 0),
      decisions_count:
        tDecisions.length,
      satisfied_count:
        tDecisions.filter(
          (decision) =>
            decision.status === 'satisfied',
        ).length,
      not_applicable_count:
        tDecisions.filter(
          (decision) =>
            decision.status === 'not_applicable',
        ).length,
      violated_count:
        tDecisions.filter(
          (decision) =>
            decision.status === 'violated',
        ).length,
      needs_review_count:
        tDecisions.filter(
          (decision) =>
            decision.status
              === 'insufficient_evidence',
        ).length,
      findings_count:
        Array.isArray(tFirst.findings)
          ? tFirst.findings.length
          : 0,
      summary:
        String(tFirst.summary ?? ''),
      metrics:
        Array.isArray(tFirst.metrics)
          ? tFirst.metrics
          : [],
    },
    finding_candidates: {
      normative_check_count:
        Array.isArray(check.findings)
          ? check.findings.length
          : 0,
      merged_count:
        Array.isArray(merged.findings)
          ? merged.findings.length
          : 0,
    },
    normative_enrichment: {
      queries_count:
        findingQuery.normative_queries?.length
        ?? 0,
      findings_with_candidates:
        findingsWithCandidates,
      candidates_count:
        candidatesCount,
    },
    normative_check: {
      summary:
        check.summary ?? '',
      findings:
        check.findings ?? [],
      metrics:
        check.metrics ?? {},
    },
    findings,
  },
};

const pageItems = $input.all().map((item) => item.json);
pageItems.sort((left, right) => left.page_number - right.page_number);
const document = pageItems[0]?.document ?? { file_name: 'document.pdf', total_pages: 0, selected_pages: [] };
const context = pageItems[0]?.project_context ?? { enabled: false };
const pages = pageItems.map(({ document: _document, project_context: _context, ...page }) => page);
const findings = pages.flatMap((page) => Array.isArray(page.findings) ? page.findings : []);

return [{
  json: {
    status: 'completed',
    source_mode: 'pdf_only',
    file_name: document.file_name,
    pdf_file_name: document.file_name,
    total_pages: document.total_pages,
    selected_pages: document.selected_pages,
    analyzed_pages: pages.length,
    findings_count: findings.length,
    summary: findings.length ? `Найдено замечаний: ${findings.length}.` : 'Замечания по выбранным листам не найдены.',
    findings,
    pages,
    explanatory_note_context: context,
    pipeline: ['document_extract','explanatory_note_validation','project_context_cache','technical_assignment_requirement_feed','page_understanding','technical_assignment_first_pass','project_context_retrieval','normative_queries','requirement_search','user_package_search','normative_check','finding_candidate_merge','finding_normative_search','experience_search','finalization'],
    limitations: ['Контекст ПЗ и пользовательские пакеты являются контекстом проекта, а не нормативным доказательством.', 'Техническое задание проверяется независимым exhaustive T-first проходом и не является нормативным доказательством.', 'T-guided retrieval используется дополнительно и не управляет сохранением T-first findings.', 'Дополнительный нормативный поиск не удаляет инженерные замечания при отсутствии подтверждения.', 'Точное расположение finding на изображении будет добавлено на этапе визуализации.'],
  },
}];

const expandedItems = $input.all().map((item) => item.json);

if (!expandedItems.length) {
  throw new Error('Understanding stage не получил PDF-страницы.');
}

return [{
  json: {
    document_id:
      $('POST /analysis/v2/pdf').first().json.body.document_id,
    expanded_items: expandedItems,
    items: expandedItems.map((item) => ({
      page_number: item.page.page_number,
      heuristic_page_type: item.page.page_type,
      extracted_text: item.page.text,
      image_base64: item.page.image_base64,
    })),
  },
}];

const source = $('Gate Collect Understanding Stage').first().json;
const expandedItems = Array.isArray(source.expanded_items)
  ? source.expanded_items
  : [];
const results = Array.isArray($json.items)
  ? $json.items
  : [];

if (results.length !== expandedItems.length) {
  throw new Error(
    `Understanding stage потерял страницы: expected=${expandedItems.length}, actual=${results.length}.`,
  );
}

return results.map((entry, index) => {
  const expanded = expandedItems[index];
  const expectedPage = Number(expanded?.page?.page_number ?? 0);
  const actualPage = Number(entry?.page_number ?? 0);

  if (!expectedPage || actualPage !== expectedPage) {
    throw new Error(
      `Understanding stage нарушил порядок страниц: expected=${expectedPage}, actual=${actualPage}.`,
    );
  }

  return {
    json: {
      page_number: actualPage,
      expanded,
      facts: entry?.result?.facts ?? {},
      understanding_metrics:
        entry?.result?.metrics ?? {},
    },
  };
});

const pageItems = $input.all().map((item) => item.json);

if (!pageItems.length) {
  throw new Error('T-first stage не получил страницы.');
}

const technicalAssignment =
  pageItems[0]?.expanded?.technical_assignment ?? {};

const requirements = Array.isArray(
  technicalAssignment.requirements,
)
  ? technicalAssignment.requirements
  : [];

if (!requirements.length) {
  throw new Error(
    'T-first включён, но atomic requirement feed пуст.',
  );
}

return [{
  json: {
    document_id:
      $('POST /analysis/v2/pdf').first().json.body.document_id,
    technical_assignment_id:
      technicalAssignment.technical_assignment_id,
    analysis_document_id:
      technicalAssignment.analysis_document_id,
    section_id:
      technicalAssignment.section_id,
    source_file:
      technicalAssignment.source_file,
    source_sha256:
      technicalAssignment.source_sha256,
    requirements,
    items: pageItems.map((item) => ({
      page_number:
        item.expanded.page.page_number,
      extracted_text:
        item.expanded.page.text,
      page_facts:
        item.facts ?? {},
      image_base64:
        item.expanded.page.image_base64,
    })),
  },
}];

const preparedPages = $('Technical Assignment First Pass')
  .all()
  .map((item) => item.json);

const augmentations = $('Augment Project Context')
  .all()
  .map((item) => item.json);

const requirements = $('Normalize Requirement Search')
  .all()
  .map((item) => item.json);

const userPackages = $input.all()
  .map((item) => item.json);

const expected = preparedPages.length;

if (
  augmentations.length !== expected
  || requirements.length !== expected
  || userPackages.length !== expected
) {
  throw new Error(
    'Normative stage потеряла page-local retrieval context.',
  );
}

return [{
  json: {
    document_id:
      $('POST /analysis/v2/pdf').first().json.body.document_id,
    items: preparedPages.map((page, index) => ({
      page_number:
        page.expanded.page.page_number,
      extracted_text:
        augmentations[index].analysis_text ?? '',
      page_facts:
        page.facts ?? {},
      normative_sources:
        requirements[index].normative_sources ?? [],
      technical_assignment_sources:
        requirements[index]
          .technical_assignment_sources ?? [],
      conflict_candidates:
        requirements[index].conflict_candidates ?? [],
      user_package_sources:
        userPackages[index].sources ?? [],
      image_base64:
        page.expanded.page.image_base64,
      normative_system_prompt:
        $('POST /analysis/v2/pdf')
          .first()
          .json.body?.normative_system_prompt
          ?? null,
    })),
  },
}];

const preparedPages = $('Technical Assignment First Pass')
  .all()
  .map((item) => item.json);

const results = Array.isArray($json.items)
  ? $json.items
  : [];

if (results.length !== preparedPages.length) {
  throw new Error(
    `Normative stage потеряла страницы: expected=${preparedPages.length}, actual=${results.length}.`,
  );
}

return results.map((entry, index) => {
  const expectedPage = Number(
    preparedPages[index]?.expanded
      ?.page?.page_number ?? 0,
  );

  const actualPage = Number(
    entry?.page_number ?? 0,
  );

  if (
    !expectedPage
    || actualPage !== expectedPage
  ) {
    throw new Error(
      `Normative stage нарушил порядок страниц: expected=${expectedPage}, actual=${actualPage}.`,
    );
  }

  return {
    json: {
      page_index: index,
      page_number: actualPage,
      ...(
        entry?.result ?? {}
      ),
    },
  };
});

